blocks.content:
// Before: no agreed order between the two threads, deadlock possible
// Thread A
lock(lock1);
lock(lock2);   // can block forever if Thread B holds lock2
do_work();
unlock(lock2);
unlock(lock1);

// Thread B
lock(lock2);
lock(lock1);   // can block forever if Thread A holds lock1
do_work();
unlock(lock1);
unlock(lock2);

