blocks.content:
// After: both threads follow the same increasing lock order
// Thread A
lock(lock1);
lock(lock2);
do_work();
unlock(lock2);
unlock(lock1);

// Thread B, now follows the same order as Thread A
lock(lock1);
lock(lock2);
do_work();
unlock(lock2);
unlock(lock1);

